/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
root=Path('/mnt/data/LSF/data/officeqa/text')
patterns=[re.compile(p,re.I) for p in [r'budget deficit', r'federal budget deficit', r'deficit .*gdp', r'as a percentage of GDP', r'percent of GDP']]
count=0
for path in sorted(root.glob('*.txt')):
    try:
        text=path.read_text(errors='ignore')
    except Exception:
        continue
    for i,line in enumerate(text.splitlines(),1):
        if any(p.search(line) for p in patterns):
            print(f'{path.name}:{i}:{line[:300]}')
            count+=1
            break
    if count>=120:
        break
print('HITS', count)
PY"

