  "rule_name": "rule_budget_year_percent",
  "file": "/mnt/data/LSF/rules/officeqa/agentic_rule_full_data_gpt54mini/all_docs/q06_what_was_the_federal_budget_deficit_for_the_most_recent_comp/rule_budget_year_percent.py",
  "code": "def rule_budget_year_percent(doc: dict) -> list[dict]:\n    try:\n        import re\n\n        spans: list[dict] = []\n        seen = set()\n        paragraphs = doc.get(\"paragraphs\") or []\n\n        percent_re = re.compile(\n            r\"(?i)\\b\\d+(?:\\.\\d+)?\\s*(?:%|percent)\\s*(?:of|as a share of|share of)\\s*(?:gdp|gnp|nominal gdp|gross national product)\\b\"\n        )\n        year_re = re.compile(r\"(?i)\\b(?:fy|fiscal(?: year)?)\\s*\\d{2,4}\\b\")\n\n        for para in paragraphs:\n            text = (para.get(\"text\") or \"\").strip()\n            low = text.lower()\n            if not text:\n                continue\n            if not percent_re.search(text):\n                continue\n            if not year_re.search(text) and \"fiscal\" not in low and \"fy\" not in low:\n                continue\n            if not any(\n                term in low\n                for term in (\n                    \"budget\",\n                    \"deficit\",\n                    \"surplus\",\n                    \"outlays\",\n                    \"receipts\",\n                    \"federal budget\",\n                    \"federal deficit\",\n                    \"federal outlays\",\n                )\n            ):\n                continue\n            key = (\n                para.get(\"page_no\"),\n                para.get(\"paragraph_no\"),\n                text,\n            )\n            if key in seen:\n                continue\n            seen.add(key)\n            spans.append({k: v for k, v in para.items() if k in {\"page_no\", \"paragraph_no\", \"text\"}})\n\n        return spans\n    except Exception:\n        return []\n",
